insert into metrics (slug, label, value, format, as_of, reporting_period, source, verified, status, sort_order) values ('submitted', 'Solutions submitted', 2384, 'number', '2025-11-30', 'Cumulative through Nov 2025', 'tradewindai.com Marketplace page', false, 'published', 0) on conflict (slug) do nothing;
