insert into metrics (slug, label, value, format, as_of, reporting_period, source, verified, status, sort_order) values ('activities', 'Participating DoW activities', 125, 'number', '2025-11-30', 'Cumulative through Nov 2025', 'tradewindai.com Marketplace page', false, 'published', 2) on conflict (slug) do nothing;
insert into metrics (slug, label, value, format, as_of, reporting_period, source, verified, status, sort_order) values ('award-value', 'Contract awards facilitated', 3260000000, 'currency-compact', '2026-02-28', 'Cumulative through Feb 2026', 'Public press reporting — pending program office confirmation', false, 'published', 3) on conflict (slug) do nothing;
insert into opportunities (slug, title, type, sponsor, summary, topics, opens_at, closes_at, recurrence, mission_need, eligibility, requirements, submission_instructions, documents, contact_email, external_url, issuing_office, featured, cta_label, cta_url, status) values ('solutions-marketplace-collection', 'Tradewinds Solutions Marketplace — Monthly Collection Period', 'marketplace-collection', 'CDAO · Tradewinds', 'The Marketplace''s ongoing solicitation. Submit a five-minute video pitch of your AI, digital or data-analytics solution for peer/SME assessment in this month''s cycle.', array['AI/ML', 'Data & Analytics', 'Digital']::text[], null, null, 'monthly', 'Department of War organizations need a fast, competitive route to mission-ready AI, digital and data-analytics capabilities. Solutions assessed as awardable are placed in the Marketplace, where government buyers can discover them and move to award.', 'Open to U.S. businesses, non-traditional defense contractors and academia, and to certain foreign entities. Confirm current eligibility terms in the official solicitation before submitting.', array['A video pitch no longer than 5:00 minutes — longer submissions are not assessed', 'A solution-provider account on the Tradewinds submission portal', 'Upload completed by 12:00 pm Eastern on the last day of the month to enter that month''s assessment']::text[], 'Create or sign in to your solution-provider account, upload your video pitch and supporting information, and submit before the monthly deadline. Submissions assessed as non-awardable receive feedback and may be revised and resubmitted in a later period.', '[{"label":"I''m Awardable — Now What? (PDF)","url":"https://storage.tradewindai.com/pdfs/Info-Sheet-Im-Awardable-Now-What.pdf"}]'::jsonb, 'success@tradewindai.com', 'https://www.tradewindai.com/tw-marketplace', 'Chief Digital and Artificial Intelligence Office', true, 'Submit through the portal', 'https://www.tradewindai.com/tw-marketplace', 'published') on conflict (slug) do nothing;
insert into contract_vehicles (slug, name, short_name, vehicle_type, vehicle_status, tagline, overview, scope, eligible_users, ordering_process, availability, documents, holders, contacts, historical_notes, pending_fields, who_it_serves, background, problem, how_it_helps, capability_label, capability_categories, service_groups, update_notice, status, sort_order) values ('test-and-evaluation', 'AI Test & Evaluation Services BPA', 'T&E', 'Blanket Purchase Agreement', 'active', 'Test technology, tools and services for AI and autonomy.', 'The AI Test and Evaluation Services BPA gives government teams a ready route to the tools, environments and expertise needed to test AI models and autonomous systems before and after they field.', array['Test technology and tools', 'Data set development and curation', 'Test harness development', 'Model output analysis', 'Test planning, documentation and reporting', 'Targeted T&E and independent verification & validation (IV&V)', 'Operational T&E', 'Human factors and user-acceptance T&E']::text[], 'Open for ordering to all agencies of the U.S. Government in support of AI test and evaluation.', array['Define the T&E requirement and confirm it falls within BPA scope', 'Contact the Tradewinds team to discuss scope and ordering', 'Develop the order package with ACC-RI', 'Compete among BPA holders and award the call order']::text[], 'Active — accepting orders', '[{"label":"T&E Services one-pager (AI.mil)","url":"https://www.ai.mil/docs/TE_One_Pager.pdf"}]'::jsonb, null, '[{"label":"Tradewinds vehicles team","email":"success@tradewindai.com"}]'::jsonb, null, array['Ordering guide', 'Current BPA holder list', 'Ordering period of performance']::text[], 'All agencies of the U.S. Government with AI or autonomy test and evaluation needs.', 'The CDAO Test and Evaluation Services Blanket Purchase Agreement meets Department needs for test technology and tools for AI and autonomy applications. CDAO manages the BPA in partnership with its prime contractors and in coordination with Army Contracting Command – Rock Island (ACC-RI).', null, null, 'Services covered', array['Commercial AI tools and services', 'Development of new AI test tools', 'Integration into environments', 'Operation and support', 'Use of tools to test models and software']::text[], '[]'::jsonb, null, 'published', 0) on conflict (slug) do nothing;
insert into contract_vehicles (slug, name, short_name, vehicle_type, vehicle_status, tagline, overview, scope, eligible_users, ordering_process, availability, documents, holders, contacts, historical_notes, pending_fields, who_it_serves, background, problem, how_it_helps, capability_label, capability_categories, service_groups, update_notice, status, sort_order) values ('draid', 'Data Readiness for AI Development', 'DRAID', 'Basic Ordering Agreement', 'pending-confirmation', 'Data readiness services that prepare data for AI development.', 'DRAID is a Basic Ordering Agreement for the data work that AI depends on — engineering, curation, quality, governance and integration — so programs start model development with data that is ready.', array['Data readiness and preparation services for AI development']::text[], 'Awaiting confirmation from the program office.', array['Contact the Tradewinds vehicles team to confirm current ordering availability']::text[], 'Current ordering status awaiting confirmation', '[]'::jsonb, null, '[{"label":"Tradewinds vehicles team","email":"success@tradewindai.com"}]'::jsonb, 'Established under JAIC. Historical information is shown separately from current ordering guidance.', array['Eligible users', 'Ordering guide', 'Holder list', 'Official documents']::text[], 'Programs that need their data prepared, governed and integrated before AI development.', 'DRAID was established under the Joint Artificial Intelligence Center (JAIC), a CDAO predecessor organization, to provide data-readiness services that prepare data for AI development.', null, null, 'Covered capabilities', array['Data science', 'Data engineering', 'Data architecture', 'Data acquisition and curation', 'Data quality and analysis', 'Synthetic data', 'Data anonymization', 'Software development', 'Enterprise information management', 'Governance', 'Cloud integration']::text[], '[]'::jsonb, 'On-ramp and ordering status are being confirmed with the program office. Contact the vehicles team before planning an order.', 'published', 1) on conflict (slug) do nothing;
insert into contract_vehicles (slug, name, short_name, vehicle_type, vehicle_status, tagline, overview, scope, eligible_users, ordering_process, availability, documents, holders, contacts, historical_notes, pending_fields, who_it_serves, background, problem, how_it_helps, capability_label, capability_categories, service_groups, update_notice, status, sort_order) values ('ai-talent-2', 'AI Talent 2.0', 'AI Talent 2.0', 'Basic Ordering Agreement', 'pending-confirmation', 'AI workforce and technical support services.', 'AI Talent 2.0 is a Basic Ordering Agreement that gives government teams access to AI technical expertise and program support when they need it.', array['AI technical management services', 'AI program management services']::text[], 'Awaiting confirmation from the program office.', array['Contact the Tradewinds vehicles team for current ordering guidance']::text[], 'Current ordering status awaiting confirmation', '[]'::jsonb, null, '[{"label":"Tradewinds vehicles team","email":"success@tradewindai.com"}]'::jsonb, null, array['Detailed task areas', 'Eligible users', 'Ordering guide', 'Holder list', 'Official documents']::text[], 'Programs that need AI technical or program-management capacity they cannot hire quickly.', null, 'AI programs depend on specialized technical talent that is scarce and slow to hire. Without it, promising efforts stall between prototype and production.', 'Pre-established agreements with qualified holders shorten the path from identifying a talent gap to having qualified support on task.', null, array[]::text[], '[{"title":"Technical management services","body":"AI and data technical expertise for programs that are building, integrating or sustaining AI capabilities."},{"title":"Program management services","body":"Program, project and acquisition management support for AI efforts."}]'::jsonb, null, 'published', 2) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('what-is-the-marketplace', 'What is the Tradewinds Solutions Marketplace?', 'The Tradewinds Solutions Marketplace is a digital repository of post-competition, readily awardable pitch videos for AI, digital and data-analytics solutions. It gives government buyers a single place to discover solutions that have already been assessed through a competitive process.', 'General Marketplace', array['all']::text[], '[{"label":"Marketplace overview","href":"/marketplace"},{"label":"Instructional videos","href":"/marketplace/videos"}]'::jsonb, 'published', 0) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('what-does-awardable-mean', 'What does “awardable” mean?', 'A solution is designated awardable when its video pitch has been assessed by a peer and subject-matter-expert panel and found to meet the Marketplace''s criteria. Awardable solutions are placed in the Marketplace, where eligible government customers can discover them and pursue an award.
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('who-can-view', 'Who can view solutions in the Marketplace?', 'Only government users with a .gov or .mil email address are given access to view the pitch-video library. Government users can search by video title or company name once signed in.', 'Government Buyer', array['government']::text[], '[{"label":"For government buyers","href":"/marketplace/government"}]'::jsonb, 'published', 2) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('provider-account-access', 'Can I see other companies'' solutions with a solution-provider account?', 'No. Solution-provider accounts are for submitting pitch videos and managing your own submissions. They do not provide access to view other solutions.', 'Vendor Submission', array['industry']::text[], '[]'::jsonb, 'published', 3) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('video-length', 'How long can my pitch video be?', 'Video pitches must not exceed five minutes (5:00). Submissions that exceed the length limitation are not assessed.', 'Vendor Submission', array['industry']::text[], '[{"label":"Exemplar submissions","href":"/marketplace/exemplars"},{"label":"Submission guide","href":"/marketplace/submission-guide"}]'::jsonb, 'published', 4) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('submission-deadline', 'When are submissions due?', 'Submissions are collected in monthly periods. Upload your video by 12:00 pm Eastern on the last day of the month to be included in that month''s assessment cycle.', 'Vendor Submission', array['industry']::text[], '[{"label":"Current collection period","href":"/opportunities/solutions-marketplace-collection"}]'::jsonb, 'published', 5) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('not-awardable', 'What happens if my solution is not determined awardable?', 'You will receive feedback from the assessment. You may revise your submission and resubmit in a later collection period.', 'Assessment and Awardable Status', array['industry']::text[], '[{"label":"Exemplar submissions","href":"/marketplace/exemplars"}]'::jsonb, 'published', 6) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('who-can-submit', 'Who can submit a solution?', 'The Marketplace accepts submissions from U.S. businesses, non-traditional defense contractors and academia, as well as certain foreign entities. Review the current solicitation for the authoritative eligibility terms.', 'Vendor Submission', array['industry']::text[], '[{"label":"Submission guide","href":"/marketplace/submission-guide"}]'::jsonb, 'published', 7) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('after-awardable', 'I''m awardable. What happens next?', 'Awardable status makes your solution discoverable to government buyers. Review the “I''m Awardable — Now What?” information sheet for guidance on approved language, use of the Awardable graphic and engaging with buyers.', 'Communications and Press', array['industry']::text[], '[{"label":"I''m Awardable — Now What? (PDF)","href":"https://storage.tradewindai.com/pdfs/Info-Sheet-Im-Awardable-Now-What.pdf"}]'::jsonb, 'published', 8) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('how-buyers-award', 'How does a government buyer make an award?', 'After identifying an awardable solution, the buying activity works with its contracting office to select an appropriate award mechanism and negotiate terms with the vendor. Contact the Tradewinds team for acquisition support.', 'Contracting and Acquisition', array['government']::text[], '[{"label":"Contract vehicles","href":"/contract-vehicles"},{"label":"Contact acquisition support","href":"/contact"}]'::jsonb, 'published', 9) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('who-runs-tradewinds', 'Who runs Tradewinds?', 'Tradewinds is housed in the Chief Digital and Artificial Intelligence Office (CDAO). The Applied Research Institute (ARI) serves as the Marketplace manager.', 'General Marketplace', array['all']::text[], '[]'::jsonb, 'published', 10) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, related_links, status, sort_order) values ('contact', 'How do I contact the Tradewinds team?', 'For program and acquisition questions email success@tradewindai.com. For account and technical issues email support@tradewindai.com.', 'General Marketplace', array['all']::text[], '[{"label":"Contact & support","href":"/contact"}]'::jsonb, 'published', 11) on conflict (slug) do nothing;
insert into resources (slug, title, kind, audiences, summary, url, date, status) values ('im-awardable-now-what', 'I''m Awardable — Now What?', 'guide', array['industry']::text[], 'Next steps after your solution is determined awardable: approved language, the Awardable graphic and engaging buyers.', 'https://storage.tradewindai.com/pdfs/Info-Sheet-Im-Awardable-Now-What.pdf', null, 'published') on conflict (slug) do nothing;
insert into resources (slug, title, kind, audiences, summary, url, date, status) values ('customer-handbook', 'Solutions Marketplace Customer Handbook (v1.2)', 'document', array['government']::text[], 'How government customers access the Marketplace, discover solutions and proceed to award.', 'https://storage.tradewindai.com/pdfs/Tradewinds-Solutions-Marketplace-Customer-Handbook-v1.2-Aug-2023_2023-08-30-143746_tawp.pdf', '2023-08-30', 'published') on conflict (slug) do nothing;
